previewCss:
.darma-loader-darma-b7-signal-bars { --accent: var(--loader-color, #3b82f6); width: var(--loader-size, 64px); height: calc(var(--loader-size, 64px) * .62); display: flex; align-items: flex-end; gap: calc(var(--loader-size, 64px) * .06); }
.darma-loader-darma-b7-signal-bars span { flex: 1; background: var(--accent); border-radius: calc(var(--loader-size, 64px) * .02); opacity: .22; animation: darma-loader-darma-b7-signal-bars-signal calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
.darma-loader-darma-b7-signal-bars span:nth-child(1) { height: 28%; animation-delay: 0s; }
.darma-loader-darma-b7-signal-bars span:nth-child(2) { height: 52%; animation-delay: calc(var(--loader-speed, 1s) * .15); }
.darma-loader-darma-b7-signal-bars span:nth-child(3) { height: 76%; animation-delay: calc(var(--loader-speed, 1s) * .3); }
.darma-loader-darma-b7-signal-bars span:nth-child(4) { height: 100%; animation-delay: calc(var(--loader-speed, 1s) * .45); }
@keyframes darma-loader-darma-b7-signal-bars-signal { 0%, 100% { opacity: .22; } 50% { opacity: 1; } }

